import{_ as n,C as i,o as r,c as l,j as t,a,b as h,w as s,E as d,a3 as c,a4 as m}from"./chunks/framework.DyX1TuK3.js";const v=JSON.parse('{"title":"Honest match","description":"","frontmatter":{},"headers":[],"relativePath":"en/honest.md","filePath":"en/honest.md"}'),u={name:"en/honest.md"};function f(g,e,p,b,y,w){const o=i("Mermaid");return r(),l("div",null,[e[1]||(e[1]=t("h1",{id:"honest-match",tabindex:"-1"},[a("Honest match "),t("a",{class:"header-anchor",href:"#honest-match","aria-label":'Permalink to "Honest match"'},"​")],-1)),e[2]||(e[2]=t("p",null,[a("The most dangerous thing a search engine can do isn't failing to find — it's "),t("strong",null,"pretending it found something when it didn't"),a('. This prototype blocks fake perfection at the last gate: when nothing in the library truly matches, it says "no match" instead of dressing the top result up as a 100% perfect hit.')],-1)),(r(),h(c,null,{default:s(()=>[d(o,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20Q%5B%22raw-sentence%20vector%20%C3%97%20library%20best%20cosine%22%5D%20--%3E%20G%7B%22clears%20confidence%20gate%3F%22%7D%0A%20%20%20%20G%20--%3E%7Cyes%7C%20H%5B%22%E2%9C%85%20normal%20display%3Cbr%2F%3Ecaps%20at%2095%25%20%C2%B7%20never%20fake%20100%25%22%5D%0A%20%20%20%20G%20--%3E%7Cno%7C%20W%5B%22%E2%9A%A0%EF%B8%8F%20warning%20'no%20strong%20match'%3Cbr%2F%3Elower%20scores%20%2B%20still%20show%20AI%20guesses%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=m('<h2 id="the-problem-relative-scores-lie-by-nature" tabindex="-1">The problem: relative scores lie by nature <a class="header-anchor" href="#the-problem-relative-scores-lie-by-nature" aria-label="Permalink to &quot;The problem: relative scores lie by nature&quot;">​</a></h2><p>Internal ranking scores are <strong>relative</strong> — RRF fusion scores and cross-encoder blends are min-max normalized, so the &quot;top of this batch&quot; always maps to 1.0.</p><p>Even when the whole result set is irrelevant, #1 still shows <strong>100%</strong>. The user sees a perfect score with no way to understand why it was picked.</p><h2 id="the-fix-confidence-gate-display-score-band" tabindex="-1">The fix: confidence gate + display score band <a class="header-anchor" href="#the-fix-confidence-gate-display-score-band" aria-label="Permalink to &quot;The fix: confidence gate + display score band&quot;">​</a></h2><p>Use the user&#39;s <strong>raw-sentence</strong> vector (not the HyDE vector — that&#39;s written to match a plot and runs high by design) to compute the best cosine against the library, as an objective yardstick for &quot;is there a true match.&quot; Good and bad queries show a clear gap:</p><table tabindex="0"><thead><tr><th>Query</th><th>top-1 cosine</th></tr></thead><tbody><tr><td>Korean crime thriller</td><td>0.626</td></tr><tr><td>cozy Mother&#39;s Day film</td><td>0.603</td></tr><tr><td>films like Parasite</td><td>0.488</td></tr><tr><td><strong>Michael Jackson (nothing relevant in library)</strong></td><td><strong>0.371</strong></td></tr></tbody></table><ul><li><strong>Match found</strong>: normal ranking, caps at 95% — never a fake 100%.</li><li><strong>No match</strong>: warning &quot;no strongly relevant results,&quot; scores lowered, but the AI&#39;s best guesses still shown for the editor to riff on.</li></ul><h2 id="where-this-rule-came-from" tabindex="-1">Where this rule came from <a class="header-anchor" href="#where-this-rule-came-from" aria-label="Permalink to &quot;Where this rule came from&quot;">​</a></h2><p>From a real incident: searching &quot;Michael Jackson,&quot; none of the 667 films were relevant, yet #1 was a war-crime drama labeled 100%. The full debugging record — symptom, root cause, measurement calibration, fix → <a href="/film-brain/en/mj-case">Debugging log</a>.</p>',9))])}const _=n(u,[["render",f]]);export{v as __pageData,_ as default};
